  "function uCard(u){const now=Date.now(),act=u.expiresAt&&u.expiresAt>now,st=!u.expiresAt?'Belum login':act?'Aktif':'Kedaluwarsa',left=act?Math.ceil((u.expiresAt-now)/864e5):0,use=S.usage&&S.usage.vu?(S.usage.vu[u.user]||0):null;",
