  "function vUsers(){return `<h2>Akun VIP</h2><p class=\"mut\" style=\"margin:4px 0 14px\">Akun yang dibuat otomatis setelah pesanan disetujui. Menghapus akun langsung mencabut akses VIP.</p>${S.users.length?S.users.map(uCard).join(''):'<div class=\"empty\">Belum ada akun VIP.</div>'}`}",
  "async function loadVip(){try{const d=await api('GET','/admin/api/vipdata');S.orders=d.orders;S.users=d.users}catch(e){toast(e.message)}}",
