  "async function loadTab(t){const tab=S.tab,jobs=[];if(['home','fitur','batas','users','trial'].includes(t))jobs.push(loadUsage());if(t==='trial')jobs.push(api('GET','/admin/api/trials').then(d=>{S.trials=d.trials}));if(['orders','users'].includes(t))jobs.push(loadVip());if(t==='musik')jobs.push(api('GET','/admin/api/music').then(d=>{S.music=d.music}));await Promise.all(jobs);if(S.tab===tab)render()}",
  "$('#tabs').onclick=async e=>{const b=e.target.closest('button');if(!b)return;S.tab=b.dataset.t;render();scrollTo(0,0);b.scrollIntoView({inline:'center',block:'nearest'});await loadTab(S.tab)};",
  "$('#app').addEventListener('click',async e=>{const t=e.target.closest('button');if(!t)return;const d=t.dataset;",
