  "/* ---------- Musik ---------- */",
  "function vMusik(){const L=S.music;let h=`<div class=\"bar2\"><div><h2>Musik</h2><p class=\"mut\" style=\"margin-top:4px\">Diputar otomatis saat situs dibuka.</p></div></div>`;",
