  "$('#app').addEventListener('change',e=>{const el=e.target.closest('[data-mti]');if(!el||!S.music)return;const m=S.music[+el.dataset.mti];if(!m)return;m.title=el.value.trim().slice(0,60)||m.title;saveMusic().then(()=>toast('Judul disimpan')).catch(x=>toast(x.message))});",
  "const rnd16=()=>Array.from(crypto.getRandomValues(new Uint8Array(8)),x=>x.toString(16).padStart(2,'0')).join('');",
  "async function saveMusic(){const r=await api('PUT','/admin/api/music',{music:S.music});S.music=r.music}",
  "$('#app').addEventListener('click',async e=>{const b=e.target.closest('[data-ma]');if(!b||!S.music)return;const [a,n]=b.dataset.ma.split(':'),L=S.music;",
  "if(a==='file'){const i=document.createElement('input');i.type='file';i.accept='audio/*';i.onchange=async()=>{const f=i.files[0];if(!f)return;try{if(f.size>5*1024*1024)throw new Error('File terlalu besar (maks 5 MB).');const C=1500000,n=Math.max(1,Math.ceil(f.size/C)),fid=rnd16(),t=($('#mu_t')?$('#mu_t').value.trim():'')||f.name.replace(/\\.[^.]+$/,'');let r;for(let k=0;k<n;k++){toast('Mengunggah '+(k+1)+'/'+n+'...');const d=await new Promise((o,x)=>{const fr=new FileReader();fr.onload=()=>o(String(fr.result).split(',')[1]||'');fr.onerror=()=>x(new Error('Gagal membaca file'));fr.readAsDataURL(f.slice(k*C,(k+1)*C))});r=await api('POST','/admin/api/music/chunk',{fid,i:k,n,title:t,data:d})}S.music=r.music;toast('Musik diunggah')}catch(x){toast(x.message)}render()};i.click();return}",
  "b.disabled=true;",
